#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    unsigned char *buf;
    size_t capacity;   /* total array size (includes 1 sentinel byte) */
    size_t head;       /* next write position */
    size_t tail;       /* next read position */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(*rb->buf));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }
    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

/* How many bytes are currently stored */
static size_t used_slots(const ringbuf_t *rb)
{
    if (rb->head >= rb->tail)
        return rb->head - rb->tail;
    return rb->capacity - rb->tail + rb->head;
}

/* Free space available for writing (total capacity minus 1 sentinel slot) */
static size_t free_slots(const ringbuf_t *rb)
{
    if (rb->head == rb->tail) {
        /* buffer is empty — all capacity is usable except the sentinel slot */
        return rb->capacity - 1;
    }
    /* full: head just after tail, or gap from head to end */
    if (rb->head > rb->tail)
        return 0;               /* ringbuf is considered "full" (reserved 1 byte for empty/full distinction) */
    /* wrap-around case: free space between head and end of buffer */
    if (rb->head <= rb->capacity - rb->tail)
        return rb->capacity - rb->head - 1; /* keep one sentinel gap */
    return rb->capacity - rb->head - 1;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    /* Maximum usable data = capacity - 1 (1 sentinel slot always reserved) */
    size_t used = used_slots(rb);
    size_t avail = rb->capacity - 1 - used;
    if (avail == 0)
        return 0;

    /* Adjust write length to fit */
    size_t actual_len = len < avail ? len : avail;

    /* How many contiguous bytes from head to end? */
    size_t run1 = actual_len;
    size_t gap_to_end = rb->capacity - rb->head;
    if (run1 > gap_to_end)
        run1 = gap_to_end;

    memcpy(rb->buf + rb->head, data, run1);
    rb->head += run1;
    if (rb->head == rb->capacity)
        rb->head = 0;

    size_t run2 = actual_len - run1;
    if (run2 > 0) {
        memcpy(rb->buf + rb->head, data + run1, run2);
        rb->head += run2;
    }

    return actual_len;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    size_t used = used_slots(rb);
    if (used == 0)
        return 0;

    size_t actual_len = len < used ? len : used;

    /* Contiguous run to end? */
    size_t run1 = actual_len;
    size_t gap_to_end = rb->capacity - rb->tail;
    if (run1 > gap_to_end)
        run1 = gap_to_end;

    memcpy(out, rb->buf + rb->tail, run1);
    rb->tail += run1;
    if (rb->tail == rb->capacity)
        rb->tail = 0;

    size_t run2 = actual_len - run1;
    if (run2 > 0) {
        memcpy(out + run1, rb->buf + rb->tail, run2);
        rb->tail += run2;
    }

    return actual_len;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    size_t used = used_slots(rb);
    if (used == 0)
        return 0;

    size_t actual_len = len < used ? len : used;
    size_t head_tmp = rb->head;
    size_t tail_tmp = rb->tail;

    /* Temporarily advance the read pointer to get data */
    size_t run1 = actual_len;
    size_t gap_to_end = rb->capacity - tail_tmp;
    if (run1 > gap_to_end)
        run1 = gap_to_end;

    memcpy(out, rb->buf + tail_tmp, run1);
    tail_tmp += run1;
    if (tail_tmp == rb->capacity)
        tail_tmp = 0;

    size_t run2 = actual_len - run1;
    if (run2 > 0) {
        memcpy(out + run1, rb->buf + tail_tmp, run2);
    }

    return actual_len;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return used_slots(rb);
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    /* Return usable capacity (total - 1 sentinel) */
    return rb->capacity > 0 ? rb->capacity - 1 : 0;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
}

#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    unsigned char *buf; /* internal storage (wraps around) */
    size_t capacity;    /* maximum number of bytes this can hold */
    size_t head;        /* next position to write */
    size_t tail;        /* next position to read */
    size_t nbytes;      /* how many valid bytes are currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)           /* must be > 0 */
        return NULL;

    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(*rb->buf));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }
    rb->capacity   = capacity;
    rb->head       = 0;
    rb->tail       = 0;
    rb->nbytes     = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

static void advance_ptr(size_t *ptr, size_t inc, size_t mod)
{
    *ptr = (mod > 0 && mod < UINT64_C(0x100000000))
           ? ((*ptr + inc) % mod)
           : (*ptr + inc);   /* guard against underflow if mod == 0 */
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    if (rb->nbytes == rb->capacity)   /* buffer full */
        return 0;

    /* How many bytes can we write? */
    size_t actual_len = rb->capacity - rb->nbytes;
    if (actual_len > len)
        actual_len = len;

    /* Write in at most two runs to handle wrap-around. */
    for (size_t written = 0; written < actual_len; ) {
        size_t run1 = rb->capacity - rb->head;   /* tail-run from head to end */
        size_t here = actual_len - written;
        if (here < run1)
            run1 = here;

        memcpy(rb->buf + rb->head, data + written, run1);
        advance_ptr(&rb->head, run1, rb->capacity);
        written += run1;
    }
    rb->nbytes += actual_len;
    return actual_len;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    if (rb->nbytes == 0)   /* buffer empty */
        return 0;

    size_t actual_len = rb->nbytes;
    if (actual_len > len)
        actual_len = len;

    for (size_t read_cnt = 0; read_cnt < actual_len; ) {
        size_t run1 = rb->capacity - rb->tail;
        size_t here = actual_len - read_cnt;
        if (here < run1)
            run1 = here;

        memcpy(out + read_cnt, rb->buf + rb->tail, run1);
        advance_ptr(&rb->tail, run1, rb->capacity);
        read_cnt += run1;
    }
    rb->nbytes -= actual_len;
    return actual_len;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0)
        return 0;

    if (rb->nbytes == 0)
        return 0;

    size_t actual_len = rb->nbytes;
    if (actual_len > len)
        actual_len = len;

    for (size_t read_cnt = 0; read_cnt < actual_len; ) {
        size_t run1 = rb->capacity - rb->tail;
        size_t here = actual_len - read_cnt;
        if (here < run1)
            run1 = here;

        memcpy(out + read_cnt, rb->buf + rb->tail, run1);
        advance_ptr(&rb->tail, run1, rb->capacity);
        read_cnt += run1;
    }
    return actual_len;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->nbytes;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->nbytes = 0;
}

#include <stdio.h>
