    uint8_t r[6] = {0};
    n = (ssize_t)rb_read(rb, r, sizeof(r));
    if (n != 4 || r[0]!=1||r[1]!=2||r[2]!=3||r[3]!=4) {
        fprintf(stderr, "fail: read %zu data %d %d %d %d\n", n,r[0],r[1],r[2],r[3]); return 1;
    }
    printf("read back [1,2,3,4] correctly\n");

    if (rb_size(rb) != 0) { fprintf(stderr, "fail: size after clear-read\n"); return 1; }

