    uint8_t tmp[6]; rb_write(rb, w,6);          /* fills remaining 0? -> wraps to tail=0 */
    rb_read(rb, tmp,4);                         /* should have read {5,6,-filled}, let's check peek */
    printf("size after wrap= %zu\n", rb_size(rb));

    /* clear */
    rb_clear(rb);
