    size_t n = rb_write(rb, w, sizeof(w));
    if (n != 4) { fprintf(stderr, "fail: wrote %zu expect 4\n", n); return 1; }
    printf("wrote %zu bytes into cap-4 buf (expect 4)\n", n);

    uint8_t r[6] = {0};
    n = rb_read(rb, r, sizeof(r));
    if (n != 4 || r[0]!=1||r[1]!=2||r[2]!=3||r[3]!=4) {
