    }
    printf("read back [1,2,3,4] correctly\n");

    if (rb_size(rb) != 0) { fprintf(stderr, "fail: size after clear-read\n"); return 1; }

    /* wrap-around test */
    rb_write(rb, w, 7);       /* should write all 6 but we have some headroom? no wait cap=4 so ... */
    uint8_t tmp[6]; rb_read(rb, tmp, 4);
    printf("after fill+clear size = %zu\n", rb_size(rb));

    /* clear test */
    rb_clear(rb);
    if (rb_size(rb) != 0) { fprintf(stderr, "fail: after clear\n"); return 1; }

