#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

int fail(const char *msg) { fprintf(stderr, "FAIL: %s\n", msg); return 1; }

int main(void) {
    /* 1. NULL / edge cases */
    if (rb_create(0) != NULL)          return fail("create(0)");
    rb_destroy(NULL);                   /* spec allows this */

    /* 2. create + capacity + size */
    ringbuf_t *rb = rb_create(4);
    if (!rb)                             return fail("allocate");
    if (rb_capacity(rb) != 4)           return fail("capacity");
    if (rb_size(rb) != 0)               return fail("new size");

    /* 3. write fills, returns exact count */
    uint8_t src1[] = {1,2,3,4};
    size_t n = rb_write(rb, src1, sizeof(src1));
    if (n != 4)                          return fail("write full");
    if (rb_size(rb) != 4)               return fail("size after fill");
    /* buffer is now full */

    uint8_t rbuf[6] = {0};
    n = rb_read(rb, rbuf, sizeof(rbuf));
    if (n != 4 || rbuf[0]!=1||rbuf[1]!=2||rbuf[2]!=3||rbuf[3]!=4)
                                            return fail("read data");
    if (rb_size(rb) != 0)               return fail("size after read");

    /* peek */
    uint8_t dst[] = {1,2,3};            /* peek with less available — should still fill what you ask */
    n = rb_write(rb, src1, 4);          /* re-fill full: [1,2,3,4] */
    if (n != 4)                         return fail("re-write");

    uint8_t pout[6];
    memset(pout, 0, sizeof(pout));
    n = rb_peek(rb, pout, 6);
    if (n != 4 || pout[0]!=1||pout[3]!=4)
                                            return fail("peek");
    /* peek must not alter size */
    if (rb_size(rb) != 4)               return fail("size after peek");

    /* clear */
    rb_clear(rb);
    if (rb_size(rb) != 0)               return fail("size after clear");

    /* 4. wrap-around: write half, read all, write again at wrap boundary */
    uint8_t a[] = {64,65};              /* bytes to trigger tail moving past middle */
    n = rb_write(rb, a, 2);             /* buf:[64,65,_,_], head=2,tail=0 */
    if (n != 2)                         return fail("wr write1");

    uint8_t peekbuf[4];
    memset(peekbuf, 0xFE, sizeof(peekbuf));
    n = rb_peek(rb, peekbuf, 4);
    /* peek should show data starting at tail without consuming */
    if (n != 2 || peekbuf[0]!=64)       return fail("peek after write");

    uint8_t tmp[3];
    n = rb_read(rb, tmp, 1);            /* read byte '0' -> reads [64], tail->1 */
    if (n != 1||tmp[0]!=64)             return fail("read 1");

    /* head=2,tail=1,buf:[65,_,_,_], size should be 1 */
    uint8_t b[] = {70,71,72};          /* write 3 but only 3 more slots; buf will wrap: [65,X,Y,Z] */
    n = rb_write(rb, b, 3);             /* writes 3 -> head goes 2->wrap->(3+1)%4=0 */
    if (n != 3)                         return fail("wr write2");
    /* now buf:[70,65,71,72], tail=1,head=0,nbytes=4 */

    uint8_t all[4];
    n = rb_read(rb, all, 4);
    if (n != 4)                         return fail("read wrap");
    /* Should read: tmp at tail(65), then rest wrapped: [71,72], then [70] from head... */
    /* Actually: tail=1 reads -> buf[1]=65, tail becomes 2; buf[2]=71,tail->3; */
    /* buf[3]=72,tail->0; tail==head==0 so done. Wait that's only reading into offset... no we need 4 bytes total */

    printf("wrap read results: ", all);  /* let's see what came out */

    if (rb_size(rb) != 0)               return fail("size after full read");

    rb_destroy(rb);
    printf("all tests passed!\n");
    return 0;
}

#include <stdio.h>
#include <assert.h>
#include "ringbuf.h"

#define ASSERT_EQ(a, b) do { if ((a)!=(b)) { fprintf(stderr,"fail at line %d: %zu != %zu\n",__LINE__,(a),(b)); return 123; } } while(0)

int main(void) {
    /* Create / destroy */
    assert(rb_create(0) == NULL);
    ringbuf_t *rb = rb_create(4);
    ASSERT_EQ(rb_capacity(rb), 4);
    ASSERT_EQ(rb_size(rb), 0);

    /* Write and read full buffer */
    uint8_t w[] = {10,20,30};
    size_t n = rb_write(rb, w, 3);
    ASSERT_EQ(n, 3);
    ASSERT_EQ(rb_size(rb), 3);
    uint8_t r[3];
    n = rb_read(rb, r, 3);
    ASSERT_EQ(n, 3);
    ASSERT_EQ(r[0],10); ASSERT_EQ(r[1],20); ASSERT_EQ(r[2],30);

    /* Wrap-around: write half, read part, write more (overwrites tail region), drain */
    rb_write(rb, w+1, 2);         /* [20,30,_,_], head=2,tail=0 */
    r[0] = 0; r[1] = 0;
    rb_read(rb, r, 2);            /* read [20,30] -> tail becomes 2, nbytes=0 */

    /* Now write 4 bytes (full capacity) - wraps head around to before tail */
    uint8_t x[] = {11,22,33,44};
    n = rb_write(rb, x, 4);       /* buf:[11,_,33,44], head=(2+4)%4=0,tail=0 */
    ASSERT_EQ(n, 4);

    uint8_t y[4];
    n = rb_read(rb, y, 4);
    ASSERT_EQ(n,4);
    ASSERT_EQ(y[0],11); ASSERT_EQ(y[1],22); ASSERT_EQ(y[2],33); ASSERT_EQ(y[3],44);

    /* Peek doesn't change buffer */
    rb_clear(rb);
    rb_write(rb, w, 3);           /* [10,20,30] */
    uint8_t pz[6]; memset(pz,0xAA,sizeof(pz));
    ASSERT_EQ(rb_peek(rb, pz, 6), 3);
    ASSERT_EQ(pz[0],10); ASSERT_EQ(pz[1],20); ASSERT_EQ(pz[2],30);
    ASSERT_EQ(rb_size(rb), 3);    /* peek didn't change size */

    /* Clear */
    rb_clear(rb); ASSERT_EQ(rb_size(rb),0);
    rb_destroy(rb); rb_destroy(NULL);

    printf("all tests passed\n");
    return 0;
}

